	@Test
	void proofGamma() {
		// Arrange + Act: ascending high-bit byte pattern (byte-order and sign-extension sensitive)
		final ProofGamma value = new ProofGamma(sweepPatternBytes(ProofGamma.SIZE, 160));

		// Assert: exact value surface
		assertThat(value.size(), equalTo(32));
		assertThat(value.toString(), equalTo("A0A1A2A3A4A5A6A7A8A9AAABACADAEAFB0B1B2B3B4B5B6B7B8B9BABBBCBDBEBF"));
		assertThat(value.toJson(), equalTo("A0A1A2A3A4A5A6A7A8A9AAABACADAEAFB0B1B2B3B4B5B6B7B8B9BABBBCBDBEBF"));
		assertThat(value.serialize(), equalTo(sweepPatternBytes(ProofGamma.SIZE, 160)));

		// Assert: generated parse arms (instance, raw bytes, hex string)
		assertThat(ProofGamma.parse(value), sameInstance(value));
		assertThat(ProofGamma.parse(sweepPatternBytes(ProofGamma.SIZE, 160)), equalTo(value));
		assertThat(ProofGamma.parse("A0A1A2A3A4A5A6A7A8A9AAABACADAEAFB0B1B2B3B4B5B6B7B8B9BABBBCBDBEBF"), equalTo(value));
	}

