	@Test
	void vrfProof() {
		// Arrange:
		final VrfProof instance = new VrfProof();

		// Act + Assert: each typed property pair, cross-checked against the descriptor-pipeline
		// getField, then re-driven through the setField arm with a second distinct value
		final ProofGamma value1 = new ProofGamma(sweepBytes(ProofGamma.SIZE, 1));
		instance.setGamma(value1);
		assertThat(instance.getGamma(), sameInstance(value1));
		assertThat(instance.getField("gamma"), sameInstance(instance.getGamma()));
		final ProofGamma value1b = new ProofGamma(sweepBytes(ProofGamma.SIZE, 51));
		instance.setField("gamma", value1b);
		assertThat(instance.getGamma(), sameInstance(value1b));
		final ProofVerificationHash value2 = new ProofVerificationHash(sweepBytes(ProofVerificationHash.SIZE, 2));
		instance.setVerificationHash(value2);
		assertThat(instance.getVerificationHash(), sameInstance(value2));
		assertThat(instance.getField("verificationHash"), sameInstance(instance.getVerificationHash()));
		final ProofVerificationHash value2b = new ProofVerificationHash(sweepBytes(ProofVerificationHash.SIZE, 52));
		instance.setField("verificationHash", value2b);
		assertThat(instance.getVerificationHash(), sameInstance(value2b));
		final ProofScalar value3 = new ProofScalar(sweepBytes(ProofScalar.SIZE, 3));
		instance.setScalar(value3);
		assertThat(instance.getScalar(), sameInstance(value3));
		assertThat(instance.getField("scalar"), sameInstance(instance.getScalar()));
		final ProofScalar value3b = new ProofScalar(sweepBytes(ProofScalar.SIZE, 53));
		instance.setField("scalar", value3b);
		assertThat(instance.getScalar(), sameInstance(value3b));

		// Assert: surface smoke — expected values are runtime-recursive; vectors own serialization
		instance.sort();
		assertDoesNotThrow(instance::toString);
		assertDoesNotThrow(instance::toJson);
		final byte[] payload = instance.serialize();
		assertThat(payload.length, equalTo(instance.size()));
		try {
			assertThat(VrfProof.deserialize(ByteBuffer.wrap(payload)).serialize(), equalTo(payload));
		} catch (RuntimeException ignored) {
			// synthetic sample rejected on the read path; vectors cover valid payloads
		}
	}

